const row = $json;

const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const phone = clean(row.phone).replace(/\D/g, '');

if (!clean(row.name) || !phone) {
  throw new Error('Each sheet row must contain name and phone');
}

const validSources = ['Google', 'Meta', 'WhatsApp', 'Website', 'Referral', 'Channel Partner', 'Other'];
const validStatuses = ['NEW', 'CONTACTED', 'FOLLOW UP', 'SITE VISIT', 'INTERESTED', 'NEGOTIATION', 'BOOKED', 'REGISTRATION COMPLETED', 'LOST'];
const source = clean(row.source);
const status = clean(row.status);

return [{
  json: {
    id: `lead-sheet-${phone}`,
    name: clean(row.name),
    phone,
    whatsapp: clean(row.whatsapp).replace(/\D/g, '') || phone,
    email: clean(row.email) || null,
    source: validSources.includes(source) ? source : 'Other',
    campaign: clean(row.campaign) || null,
    interested_site_id: clean(row.interested_site_id) || null,
    preferred_plot_size: clean(row.preferred_plot_size) || null,
    budget: clean(row.budget) || null,
    purpose: clean(row.purpose) || null,
    preferred_location: clean(row.preferred_location) || null,
    status: validStatuses.includes(status) ? status : 'NEW'
  }
}];
